+                "api.py",
+                "b.py",
+                "c.py",
+                "d_unparsed.py",
+                "fresh.py",
+                "plain.py",
+            ]
+            .into_iter()
+            .map(str::to_owned)
+            .collect();
+            let parsed = if history == "resume" {
+                vec![]
+            } else {
